<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Sorting-Algorithm Visualizer</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            background-color: #1a1a1a;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            margin: 0;
        }

        .container {
            width: 500px;
            height: 600px;
            background-color: #444;
            border-radius: 10px;
            box-shadow: 0 0 20px rgba(0,0,0,0.5);
            position: relative;
        }

        .bars-container {
            width: 100%;
            height: 40px;
            margin-bottom: 30px;
        }

        .bar {
            width: 80px;
            height: 60px;
            background-color: #e0e0e0;
            border-radius: 20px;
            position: absolute;
            top: -10px;
            left: 50%;
            transform: translateX(-50%);
            transition: height 1s, width 1s ease-out;
        }

        .bar:hover {
            background-color: #c5e0ff;
        }

        button {
            padding: 12px 25px;
            font-size: 16px;
            margin-top: 20px;
            cursor: pointer;
            border: none;
            color: white;
            background-color: #2d2d2d;
            border-radius: 8px;
            transition: background-color 0.3s;
        }

        button:hover {
            background-color: #1a1a1a;
        }

        .controls {
            margin-top: 20px;
            display: flex;
            gap: 15px;
            justify-content: center;
            flex-wrap: wrap;
        }

        .btn-sort, .btn-shuffle, .btn-reset {
            padding: 12px 25px;
            font-size: 16px;
            cursor: pointer;
        }
    </style>
</head>
<body>
    <div class="container">
        <h2>Sorting Algorithm Visualizer</h2>

        <button id="sortBtn" class="btn-sort">Sort Ascending (Step-by-Step)</button>
        <button id="shuffleBtn" class="btn-shuffle">Shuffle Array</button>
        <button id="resetBtn" class="btn-reset">Reset Array</button>

        <div class="bars-container">
            <div class="bar"></div>
            <div class="bar"></div>
            <div class="bar"></div>
            <div class="bar"></div>
            <div class="bar"></div>
            <div class="bar"></div>
            <div class="bar"></div>
            <div class="bar"></div>
        </div>
    </div>

    <script>
        // The required window API for visualization
        const window = {
            array: [],   // current array of numbers
            setArray: function(a) {
                this.array = a;
                updateBars();
            },
            sortStep: function() {
                if (this.array.length === 0) return false;

                // Simple bubble sort implementation for demonstration
                let sorted = true;
                for (let i = 0; i < this.array.length - 1; i++) {
                    for (let j = 0; j < this.array.length - 1 - i; j++) {
                        if (this.array[j] > this.array[j + 1]) {
                            // Swap elements
                            const temp = this.array[j];
                            this.array[j] = this.array[j + 1];
                            this.array[j + 1] = temp;

                            // Update bars after swap (or adjust animation)
                            updateBars();
                        }
                    }
                }

                sorted = true; // After inner loop, array is partially sorted
            },
            sorted: function() {
                return this.array.length > 0 && this.array[0] <= this.array[this.array.length - 1];
            },
            setArray: function(a) {
                window.viz.array = a;
                updateBars();
            }
        };

        // Update the bar heights based on array values
        function updateBars() {
            const container = document.querySelector('.bars-container');
            container.innerHTML = '';

            for (let i = 0; i < window.viz.array.length; i++) {
                const bar = document.createElement('div');
                bar.className = 'bar';
                bar.style.width = `${i * 80}px`;
                bar.style.height = `${window.viz.array[i] * 60}px`;

                // Assign value to bar for animation
                bar.style.backgroundColor = window.viz.array[i].toString().toUpperCase();

                container.appendChild(bar);
            }
        },

        // Initial setup with a known shuffled array (for testing)
        const testArray = [
            42, 15, 8, 30, 55, 23, 9, 19, 56, 7,
            3, 2, 1, 60, 50, 22, 33, 44, 13, 18
        ];

        // Initialize visualization with test array
        window.viz.setArray(testArray);
    </script>
</body>
</html>
